SELECT BOARD_ID, BOARD_TYPE, TITLE, ATCH_FILE_GRPID, VIEW_CNT, REGIST_DT, REGISTER FROM BOARD WHERE BOARD_TYPE = #{boardType}
AND TITLE LIKE '%' || #{searchKeyword} || '%'
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT BOARD_ID, BOARD_TYPE, TITLE, VIEW_CNT, REGIST_DT, REGISTER FROM BOARD WHERE BOARD_TYPE = #{boardType}
AND TITLE LIKE '%' || #{searchKeyword} || '%'
AND BOARD_ID < #{cursorId}
ORDER BY BOARD_ID DESC LIMIT #{limit}

mapper.update:
UPDATE BOARD
SET VIEW_CNT = COALESCE(VIEW_CNT, 0) + 1
WHERE BOARD_ID = #{boardId}
